from __future__ import annotations
import csv, io, json, os, threading
from pathlib import Path
from flask import Flask, jsonify, Response
from engine import Engine

ROOT=Path(__file__).resolve().parent
CFG=json.loads((ROOT/"config.json").read_text(encoding="utf-8"))
app=Flask(__name__)
engine=Engine(ROOT,CFG)
threading.Thread(target=engine.run,daemon=True).start()

DASHBOARD_HTML='<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>BTC Analyzer V1.4</title>\n<style>\n:root{--bg:#071019;--p:#0d1824;--p2:#101e2c;--line:#203246;--txt:#eff6ff;--muted:#8da3b8;--g:#2bd99f;--r:#ff657d;--y:#ffc85c;--b:#62a9ff;--o:#ff9c5a}\n*{box-sizing:border-box}body{margin:0;background:linear-gradient(150deg,#071019,#091725 60%,#071019);color:var(--txt);font-family:Tahoma,Arial,sans-serif}.w{max-width:1550px;margin:auto;padding:14px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}.brand h1{font-size:21px;margin:0}.sub,.note{font-size:12px;color:var(--muted);line-height:1.7}.pill,.tag{padding:6px 9px;border:1px solid var(--line);border-radius:999px;background:var(--p);font-size:11px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:10px}.c{background:linear-gradient(180deg,var(--p2),var(--p));border:1px solid var(--line);border-radius:15px;padding:13px}.s12{grid-column:span 12}.s8{grid-column:span 8}.s6{grid-column:span 6}.s4{grid-column:span 4}.s3{grid-column:span 3}.lab{font-size:11px;color:var(--muted)}.v{font-size:27px;font-weight:800;margin-top:5px}.g{color:var(--g)}.r{color:var(--r)}.y{color:var(--y)}.o{color:var(--o)}.row{display:flex;justify-content:space-between;align-items:center;gap:10px}.title{font-weight:700;margin-bottom:10px}.tfgrid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}.tf{padding:8px;border:1px solid var(--line);border-radius:10px;background:#091521;text-align:center}.tf .x{font-weight:800;margin:4px 0}.families{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.fam,.metric{padding:10px;border:1px solid var(--line);border-radius:11px;background:#091521}.bar{height:7px;background:#06101a;border-radius:10px;overflow:hidden;margin-top:7px}.fill{height:100%;background:var(--b)}.plan{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.decision{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.researchgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.reason{margin:5px 0;padding:7px 9px;border-right:3px solid var(--y);background:#0a1622;border-radius:8px;font-size:12px}.reason.good{border-color:var(--g)}.reason.bad{border-color:var(--r)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}.tw{overflow:auto;max-height:350px}.ltr{direction:ltr;text-align:center}.btn{display:inline-block;padding:7px 10px;border:1px solid var(--line);border-radius:9px;color:var(--txt);text-decoration:none;background:#0a1622;font-size:12px}\n@media(max-width:900px){.s8,.s6,.s4,.s3{grid-column:span 12}.families{grid-template-columns:repeat(3,1fr)}.tfgrid{grid-template-columns:repeat(3,1fr)}.researchgrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.families,.tfgrid,.plan,.decision,.researchgrid{grid-template-columns:repeat(2,1fr)}.w{padding:9px}.v{font-size:23px}}\n</style></head>\n<body><div class="w">\n<div class="top"><div class="brand"><h1>BTC Analyzer V1.4</h1><div class="sub">Research Memory · Persistent Storage Ready · Waves · Setup/Trigger · Paper Tracking</div></div><div><a class="btn" href="/api/research.csv">تصدير Research CSV</a> <span class="pill" id="status">...</span> <span class="pill">تحليل فقط — لا تداول حقيقي</span></div></div>\n\n<div class="grid">\n<div class="c s3"><div class="lab">BTC/USDT</div><div class="v ltr" id="price">—</div><div class="lab">السعر الحالي</div></div>\n<div class="c s3"><div class="lab">Market Bias</div><div class="v" id="bias">—</div><div class="lab" id="biasScore">—</div></div>\n<div class="c s3"><div class="lab">Signal</div><div class="v" id="action">—</div><div class="lab" id="quality">—</div></div>\n<div class="c s3"><div class="lab">Virtual Balance</div><div class="v ltr" id="balance">$100.00</div><div class="lab" id="paperStats">—</div></div>\n\n<div class="c s12"><div class="title">Decision Pipeline</div><div class="decision">\n<div class="metric"><div class="lab">SETUP</div><div class="v" style="font-size:21px" id="setupState">—</div></div>\n<div class="metric"><div class="lab">TRIGGER</div><div class="v" style="font-size:21px" id="triggerState">—</div><div class="lab" id="triggerScore"></div></div>\n<div class="metric"><div class="lab">VETO STATUS</div><div class="v" style="font-size:21px" id="vetoLevel">—</div></div>\n</div></div>\n\n<div class="c s12"><div class="title">Research Memory</div>\n<div class="researchgrid">\n<div class="metric"><div class="lab">Snapshots</div><div class="v ltr" style="font-size:21px" id="rsTotal">0</div></div>\n<div class="metric"><div class="lab">WAIT snapshots</div><div class="v ltr" style="font-size:21px" id="rsWait">0</div></div>\n<div class="metric"><div class="lab">LONG snapshots</div><div class="v ltr" style="font-size:21px" id="rsLong">0</div></div>\n<div class="metric"><div class="lab">SHORT snapshots</div><div class="v ltr" style="font-size:21px" id="rsShort">0</div></div>\n</div>\n<div class="note" id="storageNote" style="margin-top:8px">—</div>\n</div>\n\n<div class="c s8"><div class="title">خريطة الفريمات والسياق</div><div class="tfgrid" id="tfgrid"></div><div class="note" style="margin-top:8px">1Y / 6M / 3M = تحليل آخر 365 / 180 / 90 شمعة يومية.</div></div>\n<div class="c s4"><div class="title">Timeframe Hierarchy</div><div id="hierarchy"></div></div>\n\n<div class="c s6"><div class="title">Independent Confirmations</div><div class="families" id="families"></div></div>\n<div class="c s6"><div class="title">Veto & Warnings</div><div id="veto"></div></div>\n\n<div class="c s6"><div class="title">لماذا WAIT؟</div><div id="whyWait"></div></div>\n<div class="c s6"><div class="title">ما الذي ننتظره؟</div><div id="waitingFor"></div></div>\n\n<div class="c s12"><div class="title">Trade Plan — افتراضي</div><div class="plan">\n<div class="metric"><div class="lab">Entry</div><div class="v ltr" style="font-size:19px" id="entry">—</div></div>\n<div class="metric"><div class="lab">Stop / Invalidation</div><div class="v ltr" style="font-size:19px" id="sl">—</div></div>\n<div class="metric"><div class="lab">TP1 · 1.5R</div><div class="v ltr" style="font-size:19px" id="tp1">—</div></div>\n<div class="metric"><div class="lab">TP2 · 2.5R</div><div class="v ltr" style="font-size:19px" id="tp2">—</div></div>\n</div></div>\n\n<div class="c s6"><div class="title">Research by Quality</div><div class="tw"><table><thead><tr><th>Quality</th><th>N</th><th>Aligned 1H</th><th>Aligned 4H</th></tr></thead><tbody id="qualityStats"></tbody></table></div></div>\n<div class="c s6"><div class="title">Recent Research Snapshots</div><div class="tw"><table><thead><tr><th>Bias</th><th>Action</th><th>Q</th><th>MFE</th><th>MAE</th><th>1H</th><th>4H</th></tr></thead><tbody id="researchRecent"></tbody></table></div></div>\n\n<div class="c s6"><div class="title">Wave Map</div><div class="tw"><table><thead><tr><th>TF</th><th>Structure</th><th>Wave</th><th>Type</th><th>State</th><th>Change</th></tr></thead><tbody id="waves"></tbody></table></div></div>\n<div class="c s6"><div class="title">Paper Signals</div><div class="tw"><table><thead><tr><th>Side</th><th>Quality</th><th>Entry</th><th>Status</th><th>R</th></tr></thead><tbody id="signals"></tbody></table></div></div>\n</div></div>\n\n<script>\nconst $=id=>document.getElementById(id);\nconst fmt=(x,d=2)=>x==null?\'—\':Number(x).toLocaleString(\'en-US\',{minimumFractionDigits:d,maximumFractionDigits:d});\nfunction cls(x){\n if([\'BULLISH\',\'LONG\',\'UP\',\'CONFIRM\',\'TRIGGERED\',\'READY\',\'CLEAR\'].includes(x))return\'g\';\n if([\'BEARISH\',\'SHORT\',\'DOWN\',\'STRONG_VETO\',\'BLOCKED\'].includes(x))return\'r\';\n if([\'WARN\',\'SOFT_WARNING\',\'WAIT\',\'FORMING\',\'NOT_READY\'].includes(x))return\'y\';\n return\'y\';\n}\nconst labels={\n NO_CLEAR_DIRECTION:\'لا يوجد اتجاه متعدد الفريمات واضح\',CLEAR_MULTI_TIMEFRAME_BIAS:\'اتجاه واضح ومتوافق بين الفريمات\',\n ENTRY_TIMEFRAME_STRONGLY_OPPOSED:\'فريمات الدخول تعاكس الاتجاه بقوة\',INTRADAY_STRONGLY_OPPOSED:\'الفريمات القصيرة تعاكس الاتجاه بقوة\',\n MULTIPLE_CORE_FAMILIES_OPPOSED:\'أكثر من عائلة تحليل أساسية تعاكس الاتجاه\',ENTRY_OVEREXTENDED:\'السعر متمدد أكثر من اللازم\',\n REMOVE_STRONG_VETO:\'زوال سبب المنع القوي\',SETUP_STILL_FORMING:\'الإعداد ما زال في طور التكوين\',\n QUALITY_BELOW_A:\'جودة الفرصة أقل من A\',QUALITY_A_OR_BETTER:\'ارتفاع جودة الفرصة إلى A أو A+\',\n ENTRY_NOT_ALIGNED:\'توقيت الدخول غير متوافق بما يكفي\',ENTRY_SCORE_ABOVE_45:\'ارتفاع توافق فريمات الدخول\',\n LOWER_TIMEFRAMES_NOT_CONFIRMED:\'الفريمات الصغيرة لم تتزامن بعد\',LOWER_TF_SYNCHRONIZATION:\'تزامن 5m و3m و1m مع الاتجاه\',\n TRIGGER_NOT_CONFIRMED:\'شرط التنفيذ النهائي لم يتأكد\',\'15M_5M_TRIGGER\':\'تأكيد الحركة على 15m أو 5m\',\n VOLUME_AGAINST_BIAS:\'الحجم يعاكس الاتجاه\',VOLUME_IMPROVEMENT:\'تحسن تأكيد الحجم\',MACRO_WEAK:\'السياق الكبير ضعيف\',\n LONGTERM_WEAK:\'التوجه طويل المدى ضعيف\',ENTRY_ALIGNMENT_WEAK:\'توافق فريمات الدخول ضعيف\',VOLUME_OPPOSES:\'الحجم يعاكس الاتجاه\',\n DERIVATIVES_OPPOSE:\'المشتقات تعاكس الاتجاه\',MOMENTUM_OPPOSES:\'الزخم يعاكس الاتجاه\',HIGH_VOLATILITY:\'التذبذب مرتفع\',\n \'15M_WAVE_EXHAUSTING\':\'موجة 15 دقيقة تظهر إرهاقًا\',LOWER_TF_NOT_SYNCHRONIZED:\'الفريمات الصغيرة غير متزامنة\'\n};\nfunction tr(x){return labels[x]||String(x||\'\').replaceAll(\'_\',\' \')}\nfunction scoreLine(name,x){let n=Number(x||0);return `<div class="metric" style="margin-bottom:7px"><div class="row"><span class="lab">${name}</span><b class="${n>.15?\'g\':n<-.15?\'r\':\'y\'}">${(n*100).toFixed(0)}</b></div><div class="bar"><div class="fill" style="width:${Math.min(100,Math.abs(n)*100)}%"></div></div></div>`}\nfunction pct(x){return x==null?\'—\':(Number(x)>=0?\'+\':\'\')+Number(x).toFixed(2)+\'%\'}\n\nasync function refresh(){\n let s=await (await fetch(\'/api/state\')).json();\n $(\'status\').textContent=s.status||\'...\'; if(s.status!==\'OK\')return;\n $(\'price\').textContent=\'$\'+fmt(s.price,2);$(\'bias\').textContent=s.bias;$(\'bias\').className=\'v \'+cls(s.bias);$(\'biasScore\').textContent=\'Score \'+(Number(s.bias_score)*100).toFixed(0);\n $(\'action\').textContent=s.action;$(\'action\').className=\'v \'+cls(s.action);$(\'quality\').textContent=\'Quality \'+s.quality+\' · \'+Number(s.quality_score).toFixed(0)+\'/100\';\n $(\'balance\').textContent=\'$\'+fmt(s.paper?.virtual_balance,2);$(\'paperStats\').textContent=`W ${s.paper?.wins||0} / L ${s.paper?.losses||0} · WR ${Number(s.paper?.win_rate||0).toFixed(1)}%`;\n $(\'setupState\').textContent=s.setup_state;$(\'setupState\').className=\'v \'+cls(s.setup_state);\n $(\'triggerState\').textContent=s.trigger_state;$(\'triggerState\').className=\'v \'+cls(s.trigger_state);$(\'triggerScore\').textContent=\'Trigger \'+Number(s.trigger_score||0).toFixed(0)+\'/100\';\n $(\'vetoLevel\').textContent=s.veto_level;$(\'vetoLevel\').className=\'v \'+cls(s.veto_level);\n\n let r=s.research||{};\n $(\'rsTotal\').textContent=r.total_snapshots||0;$(\'rsWait\').textContent=r.wait_snapshots||0;$(\'rsLong\').textContent=r.long_snapshots||0;$(\'rsShort\').textContent=r.short_snapshots||0;\n let persistent=s.storage?.persistent_requested;\n $(\'storageNote\').innerHTML=persistent?\'<span class="g">✓ DATA_DIR configured — قاعدة البيانات تستخدم مسار التخزين المحدد.</span>\':\'<span class="y">⚠ DATA_DIR غير مضبوط. البيانات محفوظة محليًا داخل الخدمة وقد تضيع عند إعادة النشر على Render.</span>\';\n\n const order=[\'1Y\',\'6M\',\'3M\',\'1M\',\'2W\',\'12D\',\'1W\',\'3D\',\'1D\',\'12H\',\'8H\',\'6H\',\'4H\',\'2H\',\'1H\',\'30m\',\'15m\',\'5m\',\'3m\',\'1m\'];\n $(\'tfgrid\').innerHTML=order.filter(tf=>s.timeframes?.[tf]).map(tf=>{let a=s.timeframes[tf];let label=[\'1Y\',\'6M\',\'3M\'].includes(tf)?tf+\' CTX\':tf;return `<div class="tf"><div class="lab">${label}</div><div class="x ${cls(a.trend)}">${a.trend}</div><div class="lab">${a.structure}</div><div class="lab">${a.wave_direction} · ${a.wave_state}</div></div>`}).join(\'\');\n $(\'hierarchy\').innerHTML=Object.entries(s.hierarchy||{}).map(([k,v])=>scoreLine(k,v)).join(\'\');\n $(\'families\').innerHTML=Object.entries(s.families||{}).map(([k,v])=>`<div class="fam"><div class="lab">${k}</div><div class="row"><b>${(Number(v)*100).toFixed(0)}</b><span class="tag ${cls(s.confirmations?.[k])}">${s.confirmations?.[k]||\'\'}</span></div></div>`).join(\'\');\n\n let strong=s.strong_veto||[],warnings=s.warnings||[],vh=\'\';\n if(!strong.length&&!warnings.length)vh=\'<div class="g">✓ لا يوجد Veto أو تحذير حاليًا</div>\';\n if(strong.length)vh+=strong.map(x=>`<div class="reason bad">⛔ ${tr(x)}</div>`).join(\'\');\n if(warnings.length)vh+=warnings.map(x=>`<div class="reason">⚠ ${tr(x)}</div>`).join(\'\');\n $(\'veto\').innerHTML=vh;\n $(\'whyWait\').innerHTML=s.action!==\'WAIT\'?\'<div class="reason good">✓ الإشارة اجتازت شروط التنفيذ</div>\':(s.why_wait||[]).map(x=>`<div class="reason">• ${tr(x)}</div>`).join(\'\')||\'<div class="note">لا يوجد سبب مسجل.</div>\';\n $(\'waitingFor\').innerHTML=s.action!==\'WAIT\'?\'<div class="reason good">✓ لا ننتظر تأكيدًا إضافيًا</div>\':(s.waiting_for||[]).map(x=>`<div class="reason good">→ ${tr(x)}</div>`).join(\'\')||\'<div class="note">بانتظار تحديث التحليل.</div>\';\n\n let p=s.plan||{};$(\'entry\').textContent=fmt(p.entry,2);$(\'sl\').textContent=fmt(p.sl,2);$(\'tp1\').textContent=fmt(p.tp1,2);$(\'tp2\').textContent=fmt(p.tp2,2);\n\n $(\'qualityStats\').innerHTML=(r.by_quality||[]).map(x=>`<tr><td>${x.quality}</td><td>${x.n}</td><td class="ltr">${pct(x.aligned_1h_avg_pct)}</td><td class="ltr">${pct(x.aligned_4h_avg_pct)}</td></tr>`).join(\'\');\n $(\'researchRecent\').innerHTML=(r.recent||[]).map(x=>`<tr><td class="${cls(x.bias)}">${x.bias}</td><td class="${cls(x.action)}">${x.action}</td><td>${x.quality}</td><td class="ltr">${pct(x.mfe_pct)}</td><td class="ltr">${pct(x.mae_pct)}</td><td class="ltr">${pct(x.r1h_pct)}</td><td class="ltr">${pct(x.r4h_pct)}</td></tr>`).join(\'\');\n\n $(\'waves\').innerHTML=order.filter(tf=>s.timeframes?.[tf]).map(tf=>{let a=s.timeframes[tf];return `<tr><td>${tf}</td><td class="${cls(a.structure)}">${a.structure}</td><td class="${cls(a.wave_direction)}">${a.wave_direction}</td><td>${a.wave_type}</td><td>${a.wave_state}</td><td class="ltr">${Number(a.wave_change_pct).toFixed(2)}%</td></tr>`}).join(\'\');\n $(\'signals\').innerHTML=(s.paper?.recent||[]).map(x=>`<tr><td class="${x.side===\'LONG\'?\'g\':\'r\'}">${x.side}</td><td>${x.quality}</td><td class="ltr">${fmt(x.entry,2)}</td><td>${x.status}</td><td class="ltr">${Number(x.result_r||0).toFixed(1)}R</td></tr>`).join(\'\');\n}\nrefresh();setInterval(refresh,30000);\n</script>\n</body></html>'

@app.get("/")
def home():
    return Response(DASHBOARD_HTML,mimetype="text/html; charset=utf-8")

@app.get("/health")
def health():
    s=engine.snapshot()
    return jsonify({"ok":s.get("status")!="ERROR","status":s.get("status"),"error":s.get("error")})

@app.get("/api/state")
def state():
    return jsonify(engine.snapshot())

@app.get("/api/research")
def research():
    return jsonify(engine.research.stats())

@app.get("/api/research.csv")
def research_csv():
    rows=engine.research.export_rows()
    if not rows:
        return Response("no data\n",mimetype="text/csv")
    buf=io.StringIO()
    w=csv.DictWriter(buf,fieldnames=list(rows[0].keys()))
    w.writeheader()
    w.writerows(rows)
    return Response(
        buf.getvalue(),
        mimetype="text/csv",
        headers={"Content-Disposition":"attachment; filename=btc_analyzer_research.csv"}
    )

@app.get("/diag")
def diag():
    s=engine.snapshot()
    return jsonify({
      "app":"BTC Analyzer V1.4",
      "ui_embedded":True,
      "status":s.get("status"),
      "error":s.get("error"),
      "has_price":s.get("price") is not None if isinstance(s,dict) else False,
      "timeframe_count":len(s.get("timeframes",{})) if isinstance(s,dict) else 0,
      "data_provider":s.get("data_provider") if isinstance(s,dict) else None,
      "futures_status":(s.get("futures") or {}).get("status") if isinstance(s,dict) else None,
      "setup_state":s.get("setup_state") if isinstance(s,dict) else None,
      "trigger_state":s.get("trigger_state") if isinstance(s,dict) else None,
      "veto_level":s.get("veto_level") if isinstance(s,dict) else None,
      "research_snapshots":(s.get("research") or {}).get("total_snapshots") if isinstance(s,dict) else None,
      "storage":s.get("storage") if isinstance(s,dict) else None
    })

if __name__=="__main__":
    app.run(host="0.0.0.0",port=int(os.environ.get("PORT","10000")),threaded=True)
